import os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def transform(grid):
    h,w=len(grid),len(grid[0])
    cells={c:[(i,j) for i in range(h) for j in range(w) if grid[i][j]==c] for c in (4,6)}
    out=[row[:] for row in grid]
    for i,j in cells[6]: out[i][j]=0
    top=min(i for i,j in cells[4]); bot=max(i for i,j in cells[4])
    hh=bot-top+1
    for i,j in cells[4]:
        out[i+hh][j]=4   # mirrored row placed directly below: row bot+k -> bot+hh-1-k... check
    return out
